function fewestHops(hops: number[]): number {
  const n = hops.length;
  const dp = new Array(n).fill(Infinity);
  dp[0] = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j <= Math.min(n - 1, i + hops[i]); j++) {
      dp[j] = Math.min(dp[j], dp[i] + 1);
    }
  }
  return dp[n - 1];
}

