function fewestHops(hops: number[]): number {
  let used = 0, end = 0, far = 0;
  for (let i = 0; i < hops.length - 1; i++) {
    far = Math.max(far, i + hops[i]);
    if (i === end) {
      used++;
      end = far;
    }
  }
  return used;
}

